/// Icône inline avec `<use>` — alternative si on voulait un sprite SVG.
pub fn raw_svg(path: &str, size: u32) -> Markup {
    PreEscaped(format!(
        r#"<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="{path}"/></svg>"#
    ))
}
